CREATE TYPE public.app_role AS ENUM ('student','faculty','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.create_campus_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'student'); RETURN new; END; $$;
CREATE TRIGGER campus_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_campus_profile();
CREATE TABLE public.student_records (id text PRIMARY KEY, owner_id uuid REFERENCES public.profiles(id), faculty_id uuid REFERENCES public.profiles(id), record jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.student_records TO authenticated; GRANT ALL ON public.student_records TO service_role;
ALTER TABLE public.student_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY authorized_records_read ON public.student_records FOR SELECT TO authenticated USING (owner_id=auth.uid() OR (faculty_id=auth.uid() AND public.has_role(auth.uid(),'faculty')) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_records_insert ON public.student_records FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_records_update ON public.student_records FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.campus_interventions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id text NOT NULL REFERENCES public.student_records(id), created_by uuid NOT NULL REFERENCES public.profiles(id), reason text NOT NULL, action text NOT NULL, priority text NOT NULL DEFAULT 'medium', owner text NOT NULL, follow_up_date date NOT NULL, status text NOT NULL DEFAULT 'open', outcome text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.campus_interventions TO authenticated; GRANT ALL ON public.campus_interventions TO service_role;
ALTER TABLE public.campus_interventions ENABLE ROW LEVEL SECURITY;
CREATE POLICY interventions_read ON public.campus_interventions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.student_records s WHERE s.id=student_id));
CREATE POLICY interventions_create ON public.campus_interventions FOR INSERT TO authenticated WITH CHECK (created_by=auth.uid() AND EXISTS (SELECT 1 FROM public.student_records s WHERE s.id=student_id AND (public.has_role(auth.uid(),'admin') OR (s.faculty_id=auth.uid() AND public.has_role(auth.uid(),'faculty')))));
CREATE POLICY interventions_update ON public.campus_interventions FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin') OR (created_by=auth.uid() AND public.has_role(auth.uid(),'faculty'))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (created_by=auth.uid() AND public.has_role(auth.uid(),'faculty')));
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL, email text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT, SELECT ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY contact_insert ON public.contact_messages FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY contact_read ON public.contact_messages FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.campus_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, record_id text NOT NULL, operation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.campus_audit TO authenticated; GRANT ALL ON public.campus_audit TO service_role;
ALTER TABLE public.campus_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit_read ON public.campus_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_student_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at=now(); INSERT INTO public.campus_audit(actor_id,record_id,operation) VALUES(auth.uid(),NEW.id,TG_OP); RETURN NEW; END; $$;
CREATE TRIGGER student_change_audit BEFORE INSERT OR UPDATE ON public.student_records FOR EACH ROW EXECUTE FUNCTION public.audit_student_change();